"""Report figures (matplotlib, static PNG at 200 dpi). Regenerated by `python -m swarm_evidence analyze`."""
from __future__ import annotations

import statistics
from pathlib import Path

import matplotlib

matplotlib.use("Agg")
import matplotlib.pyplot as plt  # noqa: E402

from .analysis import ARM_LABEL, COLORS, GRID, INK, INK2  # noqa: E402
from .dataset import load_jsonl  # noqa: E402
from .selection import select  # noqa: E402

plt.rcParams.update({"font.family": "DejaVu Sans", "font.size": 8.5, "axes.edgecolor": INK2,
                     "axes.labelcolor": INK, "xtick.color": INK2, "ytick.color": INK2, "axes.linewidth": 0.6,
                     "axes.spines.top": False, "axes.spines.right": False, "figure.dpi": 200})


def _style(ax):
    ax.grid(axis="y", color=GRID, linewidth=0.6)
    ax.set_axisbelow(True)


def fig_example(root: Path, out: Path):
    """Figure 1: one development violating trajectory, gold events and what three selectors keep at 2k."""
    obs = {o["run_id"]: o for o in load_jsonl(root / "data/observed/trajectories.jsonl")}
    labels = {r["run_id"]: r for r in load_jsonl(root / "data/eval/labels.jsonl")}
    rid = next(r for r, l in labels.items() if l["base_case_id"] == "A1:0" and l["label"] == 1)
    o = obs[rid]
    gold = set(labels[rid]["gold_event_ids"])
    ev = o["events"]
    seq = {e["event_id"]: e["sequence"] for e in ev}
    lanes = {"W1": 3, "W2": 2, "W3": 1}
    fig, ax = plt.subplots(figsize=(7.2, 2.9))
    for e in ev:
        g = e["event_id"] in gold
        ax.scatter(e["sequence"], lanes[e["worker_id"]], s=28 if g else 9, color=INK if g else "#c3c2b7",
                   zorder=3, linewidths=0)
    # gold lineage edges
    producer = {a: e for e in ev for a in e["output_artifact_ids"]}
    for e in ev:
        if e["event_id"] not in gold:
            continue
        for a in e["input_artifact_ids"]:
            p = producer.get(a)
            if p is not None and p["event_id"] in gold:
                ax.annotate("", xy=(e["sequence"], lanes[e["worker_id"]]), xytext=(p["sequence"], lanes[p["worker_id"]]),
                            arrowprops=dict(arrowstyle="-|>", color=INK, lw=0.8, shrinkA=3, shrinkB=3), zorder=2)
    rows = [("dependency", -0.2), ("lexical", -0.7), ("chronological", -1.2)]
    for arm, y in rows:
        chosen = select(arm, o, 2000)[0]["event_ids"]
        xs = [seq[i] for i in chosen]
        hit = len(set(chosen) & gold)
        ax.scatter(xs, [y] * len(xs), marker="|", s=60, color=COLORS[arm], linewidths=1.6)
        ax.text(len(ev) + 1.5, y, f"{ARM_LABEL[arm]}: {len(chosen)} events, {hit}/{len(gold)} gold",
                va="center", fontsize=7.5, color=INK)
    for g in gold:
        ax.axvline(seq[g], ymin=0.0, ymax=1.0, color=INK, lw=0.4, ls=(0, (2, 2)), alpha=0.5, zorder=1)
    ax.set_yticks([3, 2, 1, -0.2, -0.7, -1.2])
    ax.set_yticklabels(["worker W1", "worker W2", "worker W3", "selected at 2k:", "", ""])
    ax.set_ylim(-1.6, 3.3)
    ax.set_xlim(0, len(ev) + 1)
    ax.set_xlabel("ledger sequence (finalization request arrives after the last event)")
    ax.spines["left"].set_visible(False)
    ax.tick_params(axis="y", length=0)
    fig.subplots_adjust(left=0.135, right=0.70, top=0.97, bottom=0.17)
    fig.savefig(out)
    plt.close(fig)


def fig_main(summary, model, out: Path):
    """Figure 2: held-out AUROC by selection method at two caps (LLM monitor), family-bootstrap intervals."""
    m = summary["models"].get(model)
    if not m:
        return
    arms = ["dependency", "lexical", "chronological", "bm25", "lexical_prf", "shuffled", "isolated"]
    caps = [c for c in (2000, 6000)
            if any(m["arms"].get(f"{a}@{c}") and not m["arms"][f"{a}@{c}"].get("incomplete") for a in arms)]
    if not caps:
        return
    # only caps with completed arms get a panel, so an unfinished stage never shows as an empty plot
    fig, axes = plt.subplots(1, len(caps), figsize=(3.6 * len(caps) + 0.2 * (2 - len(caps)), 2.7), sharey=True,
                             squeeze=False)
    axes = axes[0]
    full = m["arms"].get("full@nocap")
    for ax, cap in zip(axes, caps):
        xs, hs, los, his, cs = [], [], [], [], []
        for i, arm in enumerate(arms):
            a = m["arms"].get(f"{arm}@{cap}")
            if not a or a.get("incomplete"):
                continue
            xs.append(i)
            hs.append(a["auroc"])
            los.append(a["auroc"] - a["auroc_ci_family"][0])
            his.append(a["auroc_ci_family"][1] - a["auroc"])
            cs.append(COLORS[arm])
        ax.bar(xs, hs, width=0.68, color=cs, zorder=3)
        ax.errorbar(xs, hs, yerr=[los, his], fmt="none", ecolor=INK, elinewidth=0.8, capsize=2, zorder=4)
        for x, h in zip(xs, hs):
            ax.text(x, 0.03, f"{h:.2f}", ha="center", va="bottom", fontsize=7, color="white", zorder=5,
                    fontweight="bold")
        ax.axhline(0.5, color=INK2, lw=0.7, ls=(0, (3, 2)))
        if full and not full.get("incomplete"):
            ax.axhline(full["auroc"], color=COLORS["full"], lw=0.9)
            # label in the top-right corner so it never collides with bars or error bars
            ax.text(len(arms) - 0.45, 1.04, f"grey line: full log, no cap ({full['auroc']:.2f})", ha="right",
                    va="top", fontsize=6.5, color=INK2)
        ax.set_xticks(range(len(arms)))
        ax.set_xticklabels([ARM_LABEL[a].replace(" (3 calls)", "") for a in arms], rotation=30, ha="right",
                           rotation_mode="anchor", fontsize=7)
        ax.set_xlim(-0.6, len(arms) - 0.4)
        ax.set_title(f"{cap:,}-token input cap", fontsize=8.5, color=INK)
        ax.set_ylim(0, 1.05)
        _style(ax)
    axes[0].set_ylabel("held-out AUROC")
    fig.subplots_adjust(left=0.07 if len(caps) == 2 else 0.13, right=0.99, top=0.9, bottom=0.25, wspace=0.06)
    fig.savefig(out)
    plt.close(fig)


def _recall_panel(root: Path, ax):
    """Model-independent gold-evidence recall versus cap on held-out trajectories."""
    obs = {o["run_id"]: o for o in load_jsonl(root / "data/observed/trajectories.jsonl")}
    cases = {c["run_id"]: c for c in load_jsonl(root / "data/manifest/cases.jsonl")}
    labels = {r["run_id"]: r for r in load_jsonl(root / "data/eval/labels.jsonl")}
    ids = sorted(r for r, c in cases.items() if c["subset"] == "test")
    caps = [1000, 2000, 3000, 4000, 6000, 8000, 10000]
    for arm in ["dependency", "lexical", "chronological", "bm25", "isolated"]:
        ys = []
        for cap in caps:
            rec = []
            for r in ids:
                sel = {i for c in select(arm, obs[r], cap) for i in c["event_ids"]}
                g = set(labels[r]["gold_event_ids"])
                rec.append(len(sel & g) / len(g))
            ys.append(statistics.mean(rec))
        ax.plot(caps, ys, color=COLORS[arm], lw=2, marker="o", ms=3, label=ARM_LABEL[arm].replace(" (3 calls)", ""))
    for c in (2000, 6000):
        ax.axvline(c, color=INK2, lw=0.5, ls=(0, (2, 2)))
    ax.set_xlabel("input cap (estimated tokens)")
    ax.set_ylabel("gold-evidence recall")
    ax.set_ylim(0, 1.03)
    ax.set_xticks([2000, 4000, 6000, 8000, 10000])
    ax.set_xticklabels(["2k", "4k", "6k", "8k", "10k"])
    _style(ax)
    ax.legend(frameon=False, fontsize=6, loc="lower right", handlelength=1.2)
    ax.set_title("(a) evidence kept vs. cap", fontsize=8, color=INK, loc="left")


def _visibility_panel(summary, model, ax, cap, title):
    m = summary["models"][model]
    conds = ["full", "random25", "random50", "bridges"]
    names = ["full", "25%", "50%", "bridges"]
    for j, arm in enumerate(("dependency", "lexical")):
        xs, hs = [], []
        for i, c in enumerate(conds):
            v = m["visibility"].get(f"{arm}@{cap}@{c}")
            if v:
                xs.append(i + (j - 0.5) * 0.38)
                hs.append(v["auroc"])
        ax.bar(xs, hs, width=0.36, color=COLORS[arm], label=ARM_LABEL[arm], zorder=3)
        for x, h in zip(xs, hs):
            ax.text(x, h + 0.015, f"{h:.2f}", ha="center", va="bottom", fontsize=6, color=INK, rotation=90)
    ax.axhline(0.5, color=INK2, lw=0.7, ls=(0, (3, 2)))
    ax.set_xticks(range(len(conds)))
    ax.set_xticklabels(names, fontsize=6.5)
    ax.set_xlim(-0.65, 3.65)
    ax.set_xlabel("relations masked")
    ax.set_ylim(0, 1.12)
    ax.set_title(title, fontsize=8, color=INK, loc="left")
    _style(ax)


def fig_budget_and_metadata(root: Path, summary, model, out: Path):
    m = summary["models"].get(model)
    fig, axes = plt.subplots(1, 3, figsize=(7.2, 2.5), gridspec_kw={"width_ratios": [1.25, 1, 1]})
    _recall_panel(root, axes[0])
    if m and m.get("visibility"):
        _visibility_panel(summary, model, axes[1], 2000, "(b) AUROC, 2k cap")
        _visibility_panel(summary, model, axes[2], 6000, "(c) AUROC, 6k cap")
        axes[1].set_ylabel("held-out AUROC")
        axes[2].legend(frameon=False, fontsize=6, loc="upper right")
    fig.subplots_adjust(left=0.07, right=0.995, top=0.9, bottom=0.18, wspace=0.32)
    fig.savefig(out)
    plt.close(fig)


def make_all(root: Path, summary, preds, cases, labels):
    fd = root / "figures"
    fd.mkdir(exist_ok=True)
    from .protocol import PRIMARY_MODEL, SECONDARY_MODEL
    fig_example(root, fd / "fig1_example.png")
    fig_main(summary, PRIMARY_MODEL, fd / "fig2_auroc_by_method.png")
    if SECONDARY_MODEL in summary["models"]:
        fig_main(summary, SECONDARY_MODEL, fd / "figS1_auroc_by_method_secondary.png")
    fig_budget_and_metadata(root, summary, PRIMARY_MODEL, fd / "fig3_budget_and_metadata.png")
